// "Error Categories" tab: how much of the failure space the paper's four
// failure patterns explain. Data comes from public/results/error-categories.json,
// generated by analysis/build_error_categories.py from the post-audit rubric
// reviews and the qualitative codebook (analysis/coding/codebook.csv).

import { Fragment, useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';

const DATA_URL = '/results/error-categories.json';

// Categorical slots validated together (all-pairs, light surface). Pipeline and
// uncoded errors are neutral grays so the four patterns carry the color.
const COLORS = {
  'missed-renderer-defaults': '#2a78d6',
  'failed-workaround': '#eb6834',
  'layout-arithmetic': '#1baf7a',
  'encoding-mismatch': '#4a3aa7',
  pipeline: '#a8a7a1',
  uncoded: '#d6d5d0',
};

const MODEL_ORDER = ['gpt5', 'qwen', 'gemini'];

function pct(n, d, digits = 1) {
  return d ? `${((100 * n) / d).toFixed(digits)}%` : '–';
}

function Swatch({ id }) {
  return (
    <span
      aria-hidden
      className="inline-block h-2.5 w-2.5 shrink-0 rounded-sm"
      style={{ backgroundColor: COLORS[id] }}
    />
  );
}

function StatCard({ title, value, subtitle }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-white p-4">
      <p className="text-sm text-slate-500">{title}</p>
      <p className="mt-1 text-2xl font-semibold text-slate-900">{value}</p>
      {subtitle ? <p className="mt-1 text-xs text-slate-500">{subtitle}</p> : null}
    </div>
  );
}

function Section({ title, subtitle, children, right }) {
  return (
    <section className="rounded-lg border border-slate-200 bg-white p-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 className="text-sm font-semibold text-slate-900">{title}</h2>
          {subtitle ? <p className="mt-1 max-w-3xl text-xs text-slate-500">{subtitle}</p> : null}
        </div>
        {right}
      </div>
      <div className="mt-3">{children}</div>
    </section>
  );
}

// ---------------------------------------------------------------- category bars

function CategoryBars({ categories, total }) {
  const max = Math.max(...categories.map((c) => c.errors));
  return (
    <div className="space-y-2">
      {categories.map((c) => (
        <div key={c.id} className="grid grid-cols-[minmax(0,15rem)_1fr_7.5rem] items-center gap-3 text-sm">
          <div className="flex items-center gap-2 text-slate-800">
            <Swatch id={c.id} />
            <span className={c.isPattern ? 'font-medium' : 'text-slate-600'}>{c.label}</span>
          </div>
          <div className="h-4 rounded-sm bg-slate-50" title={`${c.label}: ${c.errors} errors (${pct(c.errors, total)})`}>
            <div
              className="h-4 rounded-r"
              style={{ width: `${(100 * c.errors) / max}%`, backgroundColor: COLORS[c.id] }}
            />
          </div>
          <div className="text-right tabular-nums text-slate-700">
            {c.errors} <span className="text-slate-500">· {pct(c.errors, total)}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------- pareto

function Pareto({ codes, labels, selected, onSelect }) {
  const [hover, setHover] = useState(null);
  const total = codes.reduce((s, c) => s + c.errors, 0);
  const W = 1000;
  const padL = 44;
  const padR = 12;
  const innerW = W - padL - padR;
  const step = innerW / codes.length;
  const barW = Math.max(1, step - 2);
  const maxErr = Math.max(...codes.map((c) => c.errors));
  const yMaxBars = Math.ceil(maxErr / 10) * 10;

  // Top panel: cumulative share. Bottom panel: errors per code. Shared x.
  // Layout (SVG units): caption, cumulative panel, caption, bar panel, caption.
  const topTop = 26;
  const topH = 120;
  const barTop = topTop + topH + 44;
  const barH = 170;
  const H = barTop + barH + 26;
  const topY = (p) => topTop + (1 - p) * topH;
  const barY = (v) => barTop + (1 - v / yMaxBars) * barH;

  let running = 0;
  const cum = codes.map((c) => {
    running += c.errors;
    return running / total;
  });
  const reach = (p) => cum.findIndex((v) => v >= p) + 1;
  const marks = [0.5, 0.8].map((p) => ({ p, n: reach(p) }));
  const xAt = (i) => padL + i * step + step / 2;
  const linePath = cum.map((v, i) => `${i ? 'L' : 'M'}${xAt(i).toFixed(1)},${topY(v).toFixed(1)}`).join('');

  const hovered = hover !== null ? codes[hover] : null;

  return (
    <div className="relative">
      <svg viewBox={`0 0 ${W} ${H}`} className="w-full" role="img" aria-label="Pareto chart of errors per code">
        {/* top panel grid */}
        {[0, 0.5, 1].map((p) => (
          <g key={p}>
            <line x1={padL} x2={W - padR} y1={topY(p)} y2={topY(p)} stroke="#e5e7eb" strokeWidth="1" />
            <text x={padL - 6} y={topY(p) + 4} textAnchor="end" fontSize="11" fill="#64748b">
              {Math.round(p * 100)}%
            </text>
          </g>
        ))}
        <text x={padL} y={12} fontSize="11" fontWeight="600" fill="#334155">
          Cumulative share of pattern errors
        </text>
        <text x={padL} y={barTop - 14} fontSize="11" fontWeight="600" fill="#334155">
          Errors per code
        </text>
        {marks.map(({ p, n }) => (
          <g key={p}>
            <line x1={xAt(n - 1)} x2={xAt(n - 1)} y1={topY(p)} y2={barY(0)} stroke="#94a3b8" strokeDasharray="3 3" />
            <circle cx={xAt(n - 1)} cy={topY(p)} r="4" fill="#0f172a" stroke="#fff" strokeWidth="2" />
            <text x={xAt(n - 1) + 8} y={topY(p) + 14} fontSize="11" fill="#334155">
              {n} codes → {Math.round(p * 100)}%
            </text>
          </g>
        ))}
        <path d={linePath} fill="none" stroke="#0f172a" strokeWidth="2" />

        {/* bottom panel grid */}
        {[0, yMaxBars / 2, yMaxBars].map((v) => (
          <g key={v}>
            <line x1={padL} x2={W - padR} y1={barY(v)} y2={barY(v)} stroke="#e5e7eb" strokeWidth="1" />
            <text x={padL - 6} y={barY(v) + 4} textAnchor="end" fontSize="11" fill="#64748b">
              {v}
            </text>
          </g>
        ))}
        {codes.map((c, i) => {
          const y = barY(c.errors);
          const isSel = selected === c.code;
          const dim = (hover !== null && hover !== i) || (selected && !isSel);
          return (
            <g key={c.code}>
              <rect
                x={padL + i * step + 1}
                y={y}
                width={barW}
                height={Math.max(1, barY(0) - y)}
                rx={Math.min(2, barW / 2)}
                fill={COLORS[c.category]}
                opacity={dim ? 0.35 : 1}
              />
              {/* hit target: full height, full step */}
              <rect
                x={padL + i * step}
                y={topTop}
                width={step}
                height={barY(0) - topTop}
                fill="transparent"
                onMouseEnter={() => setHover(i)}
                onMouseLeave={() => setHover(null)}
                onClick={() => onSelect(isSel ? null : c.code)}
                style={{ cursor: 'pointer' }}
              />
            </g>
          );
        })}
        <text x={padL} y={H - 6} fontSize="11" fill="#64748b">
          {codes.length} codes, sorted by number of errors
        </text>
      </svg>
      {hovered ? (
        <div
          className="pointer-events-none absolute z-10 w-72 rounded-md border border-slate-200 bg-white p-3 text-xs shadow-lg"
          style={{
            left: `${Math.min(70, Math.max(0, (xAt(hover) / W) * 100 - 10))}%`,
            top: 0,
          }}
        >
          <div className="flex items-center gap-2 font-medium text-slate-900">
            <Swatch id={hovered.category} />
            {labels[hovered.category]}
          </div>
          <p className="mt-1 text-slate-800">{hovered.code}</p>
          <p className="mt-1 tabular-nums text-slate-600">
            #{hover + 1} · {hovered.errors} errors · cumulative {pct(cum[hover] * total, total)}
          </p>
        </div>
      ) : null}
    </div>
  );
}

// ---------------------------------------------------------------- tables

function BreakdownTable({ categories, columns, getCount, columnTotals }) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full min-w-max text-left text-sm">
        <thead className="text-xs text-slate-500">
          <tr>
            <th className="py-1 pr-4 font-medium">Category</th>
            {columns.map((col) => (
              <th key={col.id} className="whitespace-nowrap py-1 pr-4 text-right font-medium">
                {col.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {categories.map((cat) => (
            <tr key={cat.id} className="border-t border-slate-100">
              <td className="py-1.5 pr-4">
                <span className="flex items-center gap-2">
                  <Swatch id={cat.id} />
                  {cat.label}
                </span>
              </td>
              {columns.map((col) => {
                const n = getCount(cat, col.id);
                return (
                  <td key={col.id} className="py-1.5 pr-4 text-right tabular-nums text-slate-700">
                    {n ? (
                      <>
                        {n} <span className="text-slate-400">({pct(n, columnTotals[col.id], 0)})</span>
                      </>
                    ) : (
                      <span className="text-slate-300">0</span>
                    )}
                  </td>
                );
              })}
            </tr>
          ))}
          <tr className="border-t border-slate-300 font-medium">
            <td className="py-1.5 pr-4">All errors</td>
            {columns.map((col) => (
              <td key={col.id} className="py-1.5 pr-4 text-right tabular-nums">
                {columnTotals[col.id]}
              </td>
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  );
}

function CodeTable({ codes, labels, models, filter, setFilter, selected, setSelected }) {
  const [query, setQuery] = useState('');
  const shown = codes.filter(
    (c) =>
      (filter === 'all' || c.category === filter) &&
      (!query || `${c.code} ${c.notes} ${c.grammars.join(' ')}`.toLowerCase().includes(query.toLowerCase())),
  );
  return (
    <div>
      <div className="mb-3 flex flex-wrap items-center gap-2">
        <select
          className="rounded-md border border-slate-300 bg-white px-2 py-1 text-sm"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
        >
          <option value="all">All categories</option>
          {Object.entries(labels).map(([id, label]) => (
            <option key={id} value={id}>
              {label}
            </option>
          ))}
        </select>
        <input
          className="w-64 rounded-md border border-slate-300 px-2 py-1 text-sm"
          placeholder="Search codes, notes, DSLs…"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <span className="text-xs text-slate-500">
          {shown.length} codes · {shown.reduce((s, c) => s + c.errors, 0)} errors
        </span>
      </div>
      <div className="max-h-[36rem] overflow-y-auto">
        <table className="w-full text-left text-sm">
          <thead className="sticky top-0 bg-white text-xs text-slate-500">
            <tr>
              <th className="py-1 pr-3 font-medium">Code</th>
              <th className="py-1 pr-3 font-medium">Category</th>
              <th className="py-1 pr-3 text-right font-medium">Errors</th>
              {MODEL_ORDER.map((m) => (
                <th key={m} className="whitespace-nowrap py-1 pr-3 text-right font-medium">
                  {models[m]}
                </th>
              ))}
              <th className="py-1 font-medium">DSLs</th>
            </tr>
          </thead>
          <tbody>
            {shown.map((c) => {
              const open = selected === c.code;
              return (
                <Fragment key={c.code}>
                  <tr
                    className={'cursor-pointer border-t border-slate-100 ' + (open ? 'bg-slate-50' : 'hover:bg-slate-50')}
                    onClick={() => setSelected(open ? null : c.code)}
                  >
                    <td className="py-1.5 pr-3 text-slate-900">
                      <span className="mr-1 text-slate-400">{open ? '▾' : '▸'}</span>
                      {c.code}
                    </td>
                    <td className="py-1.5 pr-3">
                      <span className="flex items-center gap-2 whitespace-nowrap text-slate-600">
                        <Swatch id={c.category} />
                        {labels[c.category]}
                      </span>
                    </td>
                    <td className="py-1.5 pr-3 text-right tabular-nums font-medium">{c.errors}</td>
                    {MODEL_ORDER.map((m) => (
                      <td key={m} className="py-1.5 pr-3 text-right tabular-nums text-slate-600">
                        {c.byModel[m] || <span className="text-slate-300">0</span>}
                      </td>
                    ))}
                    <td className="py-1.5 text-xs text-slate-600">{c.grammars.join(', ')}</td>
                  </tr>
                  {open ? (
                    <tr className="bg-slate-50">
                      <td colSpan={4 + MODEL_ORDER.length} className="px-6 pb-3 pt-1 text-xs text-slate-700">
                        <p className="text-slate-500">{c.axial}</p>
                        <p className="mt-1">{c.notes}</p>
                        <div className="mt-2 flex flex-wrap gap-1.5">
                          {c.cases.map((k) => (
                            <Link
                              key={`${k.model}-${k.grammar}-${k.task}`}
                              to={k.index != null ? `/result/${k.index}?runId=${encodeURIComponent(k.runId)}` : '#'}
                              onClick={() => window.scrollTo(0, 0)}
                              className="rounded border border-slate-300 bg-white px-2 py-0.5 text-slate-700 hover:border-slate-500"
                              title="Open this case"
                            >
                              {models[k.model]} · {k.grammar} · {k.task}{' '}
                              <span className="text-slate-400">{k.items.join(',')}</span>
                            </Link>
                          ))}
                        </div>
                      </td>
                    </tr>
                  ) : null}
                </Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------- page

export default function ErrorCategories() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [selected, setSelected] = useState(null);
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    let active = true;
    fetch(DATA_URL)
      .then((r) => {
        if (!r.ok) throw new Error(`Failed to load ${DATA_URL} (${r.status})`);
        return r.json();
      })
      .then((d) => active && setData(d))
      .catch((e) => active && setError(e.message));
    return () => {
      active = false;
    };
  }, []);

  const derived = useMemo(() => {
    if (!data) return null;
    const labels = Object.fromEntries(data.categories.map((c) => [c.id, c.label]));
    const patterns = data.categories.filter((c) => c.isPattern);
    const patternErrors = patterns.reduce((s, c) => s + c.errors, 0);
    const pipeline = data.categories.find((c) => c.id === 'pipeline')?.errors ?? 0;
    const patternCodes = data.codes.filter((c) => patterns.some((p) => p.id === c.category));
    let run = 0;
    const half = patternCodes.findIndex((c) => (run += c.errors) >= patternErrors / 2) + 1;
    const grammars = [...new Set(data.categories.flatMap((c) => Object.keys(c.byGrammar)))].sort();
    const modelTotals = Object.fromEntries(
      MODEL_ORDER.map((m) => [m, data.categories.reduce((s, c) => s + (c.byModel[m] ?? 0), 0)]),
    );
    const grammarTotals = Object.fromEntries(
      grammars.map((g) => [g, data.categories.reduce((s, c) => s + (c.byGrammar[g] ?? 0), 0)]),
    );
    return { labels, patternErrors, pipeline, patternCodes, half, grammars, modelTotals, grammarTotals };
  }, [data]);

  if (error) return <p className="text-sm text-rose-700">{error}</p>;
  if (!data || !derived) return <p className="text-sm text-slate-600">Loading error categories...</p>;

  const { labels, patternErrors, pipeline, patternCodes, half, grammars, modelTotals, grammarTotals } = derived;
  const total = data.totalErrors;
  const f = data.flow;

  const selectCode = (code) => {
    setSelected(code);
    if (code) {
      setFilter('all');
      setTimeout(() => document.getElementById('code-table')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 0);
    }
  };

  return (
    <div className="space-y-4">
      <div className="rounded-lg border border-slate-200 bg-white p-4">
        <h2 className="text-lg font-semibold text-slate-900">Error Categories</h2>
        <p className="mt-1 max-w-4xl text-sm text-slate-600">
          How much of the observed failure space the four failure patterns in the paper explain. One{' '}
          <span className="font-medium">error</span> is one failed rubric item on a rendered case (each case is
          scored on 11 items). Of {f.rendered} rendered cases, {f.failingCases} failed at least one item, giving{' '}
          {total} errors. Each error is assigned to exactly one qualitative code, and each code belongs to one category.
        </p>
      </div>

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard title="Errors (failed rubric items)" value={total} subtitle={`in ${f.failingCases} failing cases of ${f.rendered} rendered`} />
        <StatCard
          title="Explained by the four patterns"
          value={pct(patternErrors, total)}
          subtitle={`${patternErrors} of ${total} errors`}
        />
        <StatCard
          title="Excluding pipeline issues"
          value={pct(patternErrors, total - pipeline)}
          subtitle={`${patternErrors} of ${total - pipeline} model/DSL errors`}
        />
        <StatCard
          title="Codes within the four patterns"
          value={patternCodes.length}
          subtitle={`the top ${half} codes account for half of the errors`}
        />
      </div>

      <Section
        title="Errors by category"
        subtitle="Share of all failed rubric items. The rendering-pipeline category covers failures caused by our harness (e.g., an optional chart module or plugin not loaded), not by the model or the DSL."
      >
        <CategoryBars categories={data.categories} total={total} />
        <dl className="mt-4 grid gap-x-6 gap-y-2 text-xs text-slate-600 md:grid-cols-2">
          {data.categories.map((c) => (
            <div key={c.id} className="flex gap-2">
              <dt className="mt-0.5">
                <Swatch id={c.id} />
              </dt>
              <dd>
                <span className="font-medium text-slate-800">{c.label}.</span> {c.description}
              </dd>
            </div>
          ))}
        </dl>
      </Section>

      <Section
        title="Pareto of codes within the four patterns"
        subtitle={`Every code that explains at least one of the ${patternErrors} pattern errors, sorted by size. A few large codes and a long tail: ${half} codes cover 50% of the errors. Hover a bar for details; click to open it in the code table.`}
        right={
          <div className="flex flex-wrap gap-3 text-xs text-slate-700">
            {data.categories
              .filter((c) => c.isPattern)
              .map((c) => (
                <span key={c.id} className="flex items-center gap-1.5">
                  <Swatch id={c.id} />
                  {c.label}
                </span>
              ))}
          </div>
        }
      >
        <Pareto codes={patternCodes} labels={labels} selected={selected} onSelect={selectCode} />
      </Section>

      <div className="grid gap-4 lg:grid-cols-2">
        <Section title="By model" subtitle="Errors per category; percentages are within each model's column.">
          <BreakdownTable
            categories={data.categories}
            columns={MODEL_ORDER.map((m) => ({ id: m, label: data.models[m] }))}
            getCount={(cat, m) => cat.byModel[m] ?? 0}
            columnTotals={modelTotals}
          />
        </Section>
        <Section
          title="What is not in these counts"
          subtitle="Trials that never reached the rubric review are reported separately."
        >
          <ul className="space-y-2 text-sm text-slate-700">
            <li>
              <span className="font-medium tabular-nums">{f.trials}</span> trials (41 tasks × 10 DSLs × 3 models);{' '}
              <span className="tabular-nums">{f.noResponse}</span> returned no result.
            </li>
            <li>
              <span className="font-medium tabular-nums">{data.excluded.chartml}</span> ChartML specs failed to parse
              (the unfamiliar-schema baseline) and are discussed separately in the paper.
            </li>
            <li>
              <span className="font-medium tabular-nums">{data.excluded.renderFailure}</span> specs in other DSLs
              failed JSON validation or rendering; these were not rubric-reviewed or coded.
            </li>
            <li>
              <span className="font-medium tabular-nums">{f.passingCases}</span> rendered cases passed all 11 rubric
              items.
            </li>
            <li>
              Of the {f.failingCases} failing cases, {data.caseKinds.withPattern} have at least one error in the four
              patterns, {data.caseKinds.pipelineOnly} fail only because of pipeline issues, and{' '}
              {data.caseKinds.uncodedOnly ?? 0} only on uncoded items.
            </li>
          </ul>
        </Section>
      </div>

      <Section title="By DSL" subtitle="Errors per category; percentages are within each DSL's column.">
        <BreakdownTable
          categories={data.categories}
          columns={grammars.map((g) => ({ id: g, label: g }))}
          getCount={(cat, g) => cat.byGrammar[g] ?? 0}
          columnTotals={grammarTotals}
        />
      </Section>

      <div id="code-table">
        <Section
          title="Codebook"
          subtitle="All codes with at least one assigned error. Click a row for the code's description and links to every case it covers (failed rubric items in gray)."
        >
          <CodeTable
            codes={data.codes}
            labels={labels}
            models={data.models}
            filter={filter}
            setFilter={setFilter}
            selected={selected}
            setSelected={setSelected}
          />
        </Section>
      </div>
    </div>
  );
}
